import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.BkFmai_x.js";const u=JSON.parse('{"title":"Android (MAUI)","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/android.md","filePath":"platforms/android.md","lastUpdated":1784683307000}'),n={name:"platforms/android.md"};function s(i,e,d,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="android-maui" tabindex="-1">Android (MAUI) <a class="header-anchor" href="#android-maui" aria-label="Permalink to &quot;Android (MAUI)&quot;">​</a></h1><p><code>VaultGuard.App</code> is a .NET MAUI app - Blazor Hybrid, so it hosts the same <code>VaultGuard.Components.Shared</code> UI the web app uses, wrapped in a native shell. It multi-targets <code>net10.0-android</code> (plus Windows/iOS/ MacCatalyst depending on host OS) and talks to <code>VaultGuard.API</code> over HTTP with an <a href="/PasswordManagerApp/api/reference#authentication">API key</a> rather than running the core in-process.</p><div class="warning custom-block"><p class="custom-block-title">Screenshots not yet available</p><p>This build environment has no Android emulator, so there&#39;s no way to capture real screenshots here. Once someone takes them from a device or emulator, drop them into <code>screenshots/mobile/android/{dark,light}/</code> in the repository and they&#39;ll show up here automatically.</p></div><h2 id="connecting-to-a-server" tabindex="-1">Connecting to a server <a class="header-anchor" href="#connecting-to-a-server" aria-label="Permalink to &quot;Connecting to a server&quot;">​</a></h2><p>On first launch, the app asks for the API URL and an <a href="/PasswordManagerApp/guide/getting-started#getting-an-api-key-for-mobile-the-browser-extension">API key</a> generated from the web app. Both can be changed later in <strong>Settings → Storage → API Configuration</strong>.</p>',5)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
